                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.jan_planning_overall as with targets as ( select date, replace(sales_total,\',\',\'\')::int as target_sales, 1250 as target_asp, 0.13 as discount_pct, ((replace(sales_total,\',\',\'\')::int*0.13)/(0.87))::int as target_discount_amount, (replace(sales_total,\',\',\'\')::int/1265)::int as target_quantity, ((replace(sales_total,\',\',\'\')::int/5.5)*1)::int as target_total_spend, (((replace(sales_total,\',\',\'\')::int/5.5)*0.85)*1)::int as target_fb_spend, (((replace(sales_total,\',\',\'\')::int/5.5)*0.09)*1)::int as target_google_spend, (((replace(sales_total,\',\',\'\')::int/5.5)*0.06)*1)::int as target_retention_affilate_spend from snitch_db.maplemonk.FEB26_PLANNING where date is not null ), sales_discount as ( select date, sum(gross_sales::int) as sales, sum(total_discount::int)/sum(total_discount::int+gross_sales::int) as discount_pct, sum(total_discount::int) as discount from snitch_db.maplemonk.sales_cost_source_snitch group by 1 ), main_spends as ( select date, sum(case when channel = \'Facebook\' then spend end)::int-ifnull(((sum(case when channel = \'Facebook\' and (lower(ad_name) like \'brand%\' or lower(adset_name) like \'brand%\') then spend end)::int)),0)-ifnull(sum(case when channel = \'Facebook\' and (lower(ad_name) like \'offline%\' or lower(adset_name) like \'offline%\') then spend end)::int,0)-ifnull(sum(case when channel = \'Facebook\' and (lower(ad_name) like \'plus%\' or lower(adset_name) like \'plus%\') then spend end)::int,0) as facebook, sum(case when channel = \'Google\' then spend end)::int-ifnull(((sum(case when channel = \'Google\' and (lower(ad_name) like \'%brand%\' or lower(adset_name) like \'%brand%\' or lower(campaign_name) like \'%brand%\') then spend end)::int)),0)-ifnull(sum(case when channel = \'Google\' and (lower(ad_name) like \'%offline%\' or lower(adset_name) like \'%offline%\' or lower(campaign_name) like \'%